import{_ as d,o as r,c as e,a2 as o}from"./chunks/framework.DoCD98hS.js";const u=JSON.parse('{"title":"远程组件的代价","description":"","frontmatter":{},"headers":[],"relativePath":"guide/remote-costs.md","filePath":"guide/remote-costs.md","lastUpdated":1795586866000}'),a={name:"guide/remote-costs.md"};function l(i,t,n,h,s,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="远程组件的代价" tabindex="-1">远程组件的代价 <a class="header-anchor" href="#远程组件的代价" aria-label="Permalink to &quot;远程组件的代价&quot;">​</a></h1><p>远程组件把「改一行代码就要全量发版」变成「加载一个已发布的实现」。省下来的成本没有消失，它转移到了排查、流量、版本和契约上。接入之前，这几项值得先摊开谈。</p><h2 id="一张总表" tabindex="-1">一张总表 <a class="header-anchor" href="#一张总表" aria-label="Permalink to &quot;一张总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>代价</th><th>具体表现</th><th>谁会先撞上</th></tr></thead><tbody><tr><td>排查链变长</td><td>一个组件白屏，可能是站点、meta、UMD、成员名、注册时机、框架实例六层里任意一层</td><td>接入方</td></tr><tr><td>静态资源被直接引用</td><td>公开目录里的产物没有任何来源校验，别的站点一条 <code>&lt;script src&gt;</code> 就能用</td><td>提供方</td></tr><tr><td>版本漂移</td><td>产物以文件名覆盖上传，没有内容哈希，缓存与新旧产物混用</td><td>双方</td></tr><tr><td>构建顺序耦合</td><td>消费方要构建，提供方的产物必须先就位</td><td>接入方</td></tr><tr><td>外部依赖</td><td>在线编辑器之类的能力依赖公网编译器与高亮资源，网络受限即不可用</td><td>接入方</td></tr><tr><td>体积与首屏</td><td>站点级产物往往十几 MB，移动网络下很贵</td><td>接入方</td></tr><tr><td>契约靠约定</td><td>成员名没有机器校验，拼错就是 <code>undefined</code>，不报错</td><td>双方</td></tr><tr><td>供应链</td><td>远程实现跑在宿主页面的全局上，对方目录被改，所有宿主一起受影响</td><td>双方</td></tr></tbody></table><h2 id="排查为什么变长" tabindex="-1">排查为什么变长 <a class="header-anchor" href="#排查为什么变长" aria-label="Permalink to &quot;排查为什么变长&quot;">​</a></h2><p>本地引一个 npm 包，报错通常指向你的代码。引一个远程实现，错误可能来自任何一层：</p><ul><li>托管目录不可达，或换了部署前缀而调用方没跟着改；</li><li><code>hel-meta.json</code> 能拿到，但里面指向的 chunk 地址已经失效；</li><li>产物加载成功，但导出名和你写的标签名不是同一个；</li><li>宿主没把成员注册成全局组件，模板里写了标签却没人解析；</li><li>框架实例加载了两份，组件能渲染但不联动。</li></ul><p>这几种在页面上几乎都长得一样：一块空白，或者一个未解析的标签。控制台里往往只有一句「某成员不存在」，看不出是哪一层出的问题。构建期更容易骗人：某个导出取不到，构建照样成功，只在日志里留一行 warning，真正炸是在运行时。</p><p>在线编辑器里排查还要再难一层——预览运行在独立文档里，跨域时拿不到它的控制台输出，白屏和报错的界面表现完全一致。</p><h2 id="静态资源被直接引用" tabindex="-1">静态资源被直接引用 <a class="header-anchor" href="#静态资源被直接引用" aria-label="Permalink to &quot;静态资源被直接引用&quot;">​</a></h2><p>产物目录是公开只读的静态目录，任何知道路径的人都能直接引用，没有来源校验，也没有配额。后果分三种：</p><ol><li>别人的站点把它当免费 CDN，带宽你出、故障你背；</li><li>用量统计失真，不知道到底谁在用、用了多少；</li><li>一旦你调整目录或产物结构，对方页面先崩，问题反馈不到你这儿。</li></ol><p>反过来也要承认这是它的价值：不需要账号、不需要 token、不限制来源，正是这一点让它能被任意环境最快地接进去。要不要收紧，取决于你更在意「接得方便」还是「用得可控」。</p><h3 id="收紧的几种做法与代价" tabindex="-1">收紧的几种做法与代价 <a class="header-anchor" href="#收紧的几种做法与代价" aria-label="Permalink to &quot;收紧的几种做法与代价&quot;">​</a></h3><p>按强度从低到高排，每加一层都会牺牲一部分「拿来就能用」的便利。</p><table tabindex="0"><thead><tr><th>做法</th><th>挡住什么</th><th>代价</th></tr></thead><tbody><tr><td><code>Referer</code> 白名单</td><td>普通站点直接引用</td><td><code>Referer</code> 可伪造，只能过滤误用和随手引用</td></tr><tr><td>CORS 来源白名单</td><td>跨域脚本的读取</td><td>对 <code>&lt;script src&gt;</code> 无效，标签加载不走 CORS</td></tr><tr><td>请求头校验</td><td>无头引用</td><td><code>&lt;script&gt;</code> 无法自定义头，会废掉直接在 HTML 里引的能力</td></tr><tr><td>签名地址（带过期时间）</td><td>长期白嫖、把地址当免费 CDN</td><td>地址随票据变化，缓存命中率下降，调用方要接签发</td></tr><tr><td>私有读对象存储</td><td>绕过签发的一切访问</td><td>接入方必须先拿到票据，冷启动路径变长</td></tr><tr><td>目录级限流与配额</td><td>高频刷量</td><td>正常高峰也会被限，需要单独定阈值</td></tr></tbody></table><p>现实中的组合通常是：<strong>公开包保持开放</strong>（它的价值就在免接入），<strong>体积大或含业务配方的产物走签名</strong>，再加一条限流兜底。完整性校验（<code>integrity</code>）不算防盗链——它防的是内容被替换，挡不住别人引你的资源。</p><h3 id="期限要一起定" tabindex="-1">期限要一起定 <a class="header-anchor" href="#期限要一起定" aria-label="Permalink to &quot;期限要一起定&quot;">​</a></h3><p>只上策略不定期限，最后一定变成「谁都不敢删、谁也不敢改」。</p><table tabindex="0"><thead><tr><th>项</th><th>建议取值</th><th>说明</th></tr></thead><tbody><tr><td>观察期</td><td>7 天只告警不拦截</td><td>先看清到底谁在引、引了多少，再决定拦不拦</td></tr><tr><td>迁移期</td><td>30 天</td><td>通知到现有引用方，期间新旧策略并行</td></tr><tr><td>票据有效期</td><td>10 分钟量级</td><td>够一次页面加载，不足以被转存复用</td></tr><tr><td>产物保留</td><td>最近 3 个版本，且不少于 30 天</td><td>回滚只换指针，不做重新发布</td></tr><tr><td>回收</td><td>过期即刻删除</td><td>删除前先确认没有调用方还在拿旧地址</td></tr></tbody></table><h2 id="其他几处容易被忽略的地方" tabindex="-1">其他几处容易被忽略的地方 <a class="header-anchor" href="#其他几处容易被忽略的地方" aria-label="Permalink to &quot;其他几处容易被忽略的地方&quot;">​</a></h2><ul><li><strong>版本不是不可变的</strong>：同一个目录反复覆盖写入，同一个地址在不同时刻可能是两份代码。中间加缓存层之后，新旧混用的概率会明显上升。</li><li><strong>兜底源可能反而更旧</strong>：自托管目录与 npm 上的版本不同步时，「主源失败就回退」会把请求引到一份更旧的实现，表现是「有时候对有时候不对」。</li><li><strong>构建顺序是硬约束</strong>：提供方产物没就位，消费方构建出来的地址就是空的；这条约束不会因为工具链好看而消失。</li><li><strong>契约没有校验</strong>：导出的成员名靠口头约定，拼错不报错，只是渲染不出来。命名冲突也一样——示例里的默认导出和导入进来的成员同名，编译器直接报重复声明。</li><li><strong>本地通了不代表线上通</strong>：本地入口、公共基址、发布目标三者的差异，常常在发布前一步才暴露，而报错信息指向的是环境变量而不是那行配置。</li></ul><h2 id="怎么处理" tabindex="-1">怎么处理 <a class="header-anchor" href="#怎么处理" aria-label="Permalink to &quot;怎么处理&quot;">​</a></h2><p>按「谁有能力做」分三层，不要混在一起谈。</p><p><strong>接入方可以自己先兜住的</strong></p><ul><li>固定版本而不是跟随目录：引用带版本或内容哈希的地址，避免同一地址在不同时刻是两份代码。</li><li>给关键产物加完整性校验，加载前后都能确认拿到的是预期内容。</li><li>本地做一层失败兜底：主源拿不到就用备用源，并且明确提示「当前是降级状态」，不要让用户以为组件坏了。</li><li>对核心页面准备降级形态（静态图、精简组件），远程不可达时不至于整块空白。</li></ul><p><strong>提供方应当给出的</strong></p><ul><li>失败要可读：区分「地址拿不到」「产物解析失败」「成员不存在」三种提示，而不是统一白屏。</li><li>契约要可查：把每个包真实导出的成员列成清单，构建时对着校验，不依赖记忆。</li><li>版本要可回溯：发布保留最近若干份产物，回滚是换一个指针，而不是重新发一次。</li><li>地址要跟站点走：生成或引用时用相对路径加当前站点，不把固定域名写进产物。</li></ul><p><strong>需要双方坐下来约定的</strong></p><table tabindex="0"><thead><tr><th>事项</th><th>建议约定</th></tr></thead><tbody><tr><td>发布窗口</td><td>高频改动的包错峰发布，避免接入方大促或演示当天遇到产物变更</td></tr><tr><td>兼容范围</td><td>明确「哪些变更会破坏调用方」，破坏性变更提前通知并保留一个过渡版本</td></tr><tr><td>回滚责任</td><td>出问题时谁执行回滚、多久内完成、回滚后由谁验证</td></tr><tr><td>流量归属</td><td>如果确实要把公开引用收紧，先给出现有调用方的清单和迁移期</td></tr><tr><td>问题反馈</td><td>指定一个统一的反馈入口，避免问题散落在各人聊天窗口</td></tr></tbody></table><h2 id="和模块联邦比-这个问题一样吗" tabindex="-1">和模块联邦比，这个问题一样吗 <a class="header-anchor" href="#和模块联邦比-这个问题一样吗" aria-label="Permalink to &quot;和模块联邦比，这个问题一样吗&quot;">​</a></h2><p>一样有，而且有几项更重，只是表现形式不同。</p><table tabindex="0"><thead><tr><th>维度</th><th>远程组件（本仓库做法）</th><th>模块联邦</th></tr></thead><tbody><tr><td>被第三方直接引用</td><td>一个 UMD 文件即可，门槛最低</td><td>要会写容器初始化与取模块的几行运行时，门槛更高</td></tr><tr><td>来源校验</td><td>同样没有，默认全公开</td><td>同样没有，<code>remoteEntry</code> 也是公开静态文件</td></tr><tr><td>版本漂移</td><td>目录覆盖写入，缓存混用</td><td><code>remoteEntry</code> 覆盖更新，chunk 名带哈希，容易出现「加载 chunk 失败」</td></tr><tr><td>依赖一致性</td><td>框架实例靠全局注入，需按名注册</td><td>共享依赖要做单例协商，<code>requiredVersion</code> 不匹配时行为不确定</td></tr><tr><td>隔离</td><td>视方案而定，可用沙箱文档隔离</td><td>无沙箱，代码直接跑在宿主上下文，样式与全局变量互相污染</td></tr><tr><td>出错表现</td><td>白屏、未解析标签</td><td>容器初始化失败、共享模块不可用、chunk 404，提示更晦涩</td></tr></tbody></table><p>结论是：<strong>模块联邦同样会被白嫖</strong>，因为 <code>remoteEntry</code> 没有任何来源限制。技术上完全可行——用 <code>&lt;script&gt;</code> 把 <code>remoteEntry.js</code> 引进来，调容器名的 <code>init()</code>，再 <code>get()</code> 取出模块即可；甚至可以跳过共享依赖初始化，直接拿远程自带的那份依赖，体积大一点但能跑。</p><p>门槛差别在熟练度：远程组件这边一个 UMD 文件、从页面全局取成员就能用，随手引用的概率高；模块联邦得懂它的运行时协议和初始化时序，概率低，但风险等级一样——<strong>没被授权就是没被授权，能不能做到只是知识问题</strong>。</p><p>模块联邦真正更难受的地方在别处，而且比白嫖要命：</p><ul><li><strong>没有沙箱</strong>。远程模块直接跑在宿主页面的全局上下文里，全局变量、原型链、样式全部共享。有文档隔离或代理隔离的方案至少还隔了一层，模块联邦没有，所以对方产物被改动时，宿主是直接受影响的。</li><li><strong>共享依赖要协商</strong>。单例配置错了就是两份框架运行时，现象是组件能渲染但不联动，报错往往只指出调用处，不指出来源。要求版本不匹配时，究竟是回退到本地那份还是直接抛错，取决于打包器与加载顺序，不是确定行为。</li><li><strong><code>remoteEntry</code> 与 chunk 的版本必须同时更新</strong>。入口文件覆盖上传、chunk 文件名带哈希，旧入口配新目录就是「加载某 chunk 失败」；而入口文件本身往往被浏览器或 CDN 缓存着，你清不掉对方的缓存。</li><li><strong>报错更难读</strong>。共享模块不可用、容器初始化失败这类提示，比远程组件这边的「成员不存在」更难往下追一层。</li></ul><p>这两套方案有一个共同的病根：<strong>产物以文件名覆盖写入，没有内容哈希</strong>。上一节说的「版本不是不可变的」，模块联邦一样有，只是它把后果放大成了 chunk 404。</p><p>选择时真正要比较的不是「有没有缺点」，而是「缺点落在谁身上」：远程组件把复杂度压在接入方的排查上，模块联邦把复杂度压在双方的构建配置和运行时协商上。两者都没有解决「公开静态资源默认对所有人开放」这件事——那是部署策略层面的问题，方案本身给不了答案。</p><h2 id="一个务实的判断" tabindex="-1">一个务实的判断 <a class="header-anchor" href="#一个务实的判断" aria-label="Permalink to &quot;一个务实的判断&quot;">​</a></h2><p>远程组件适合这样的场景：同一个实现要被多个宿主复用、宿主发版成本远高于组件本身、且双方能接受「出问题时多一层排查」。如果只是单仓库内复用，或者这个组件恰好是核心页面里最不能出问题的那一块，本地依赖加一次构建，通常比换来一层远程加载更划算。</p><p>代价本身不是问题，没被提前说清楚的代价才是。</p>',42)])])}const b=d(a,[["render",l]]);export{u as __pageData,b as default};
